/* MEASURE-7, RU-56 candidate c: hover 14 %, current 32 %, press 40 % of the dock's ink over the plate, on .glass-dock */
.glass-dock {
    --dock-control-hover-bg: color-mix(in oklab, var(--dock-fg-on-aurora) 14%, transparent);
    --dock-control-active-bg: color-mix(in oklab, var(--dock-fg-on-aurora) 32%, transparent);
    --dock-control-press-bg: color-mix(in oklab, var(--dock-fg-on-aurora) 40%, transparent);
    --glass-capsule-fill: color-mix(in oklab, var(--dock-fg-on-aurora) 32%, transparent);
}
